mapper.select:
SELECT COUNT(*)
FROM public.tb_notification
WHERE tenant_id = #{tenantId}
  AND recipient_user_id = #{userId}
  AND read_at IS NULL
  AND archived_at IS NULL

SELECT n.notification_id AS notificationId, n.event_type AS eventType, n.source_type AS sourceType, n.source_id AS sourceId, c.owner_id AS targetId, n.title, n.summary, n.created_at AS createdAt, n.read_at AS readAt FROM public.tb_notification n LEFT JOIN public.tb_common_comment c ON n.source_type = 'APPROVAL_COMMENT' AND c.tenant_id = n.tenant_id AND c.comment_id = n.source_id AND c.owner_type = 'APPROVAL' WHERE n.tenant_id = #{tenantId} AND n.recipient_user_id = #{userId} AND n.archived_at IS NULL
AND n.read_at IS NULL
AND n.event_type = #{eventType}
AND n.notification_id < #{beforeNotificationId}
ORDER BY n.created_at DESC, n.notification_id DESC LIMIT #{limit}

mapper.update:
UPDATE public.tb_notification
SET read_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND recipient_user_id = #{userId}
  AND notification_id = #{notificationId}
  AND read_at IS NULL
  AND archived_at IS NULL

UPDATE public.tb_notification
SET archived_at = COALESCE(archived_at, CURRENT_TIMESTAMP)
WHERE tenant_id = #{tenantId}
  AND recipient_user_id = #{userId}
  AND notification_id = #{notificationId}

UPDATE public.tb_notification
SET archived_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND recipient_user_id = #{userId}
  AND read_at IS NOT NULL
  AND archived_at IS NULL

      AND event_type = #{eventType}

mapper.insert:
INSERT INTO public.tb_notification (
    tenant_id, recipient_user_id, event_type, source_type, source_id, title, summary
) VALUES (
    #{tenantId}, #{recipientUserId}, #{eventType}, #{sourceType}, #{sourceId}, #{title}, #{summary}
)
ON CONFLICT (tenant_id, recipient_user_id, event_type, source_type, source_id) DO NOTHING
